    ja_osa:  'jpn', // Japanese (regional-variant of jpn)
    ja_aom:  'jpn',
    ja_hak:  'jpn',
    ja_kyo:  'jpn',
    ja_hir:  'jpn',
    ja_kg:   'jpn',
    ja_sd:   'jpn',
    ko_kp:   'kor', ko_bus: 'kor', ko_yb: 'kor', ko_hg: 'kor', ko_jl: 'kor',
    zh_db: 'cmn', zh_sc: 'cmn', zh_jh: 'cmn', zh_tj: 'cmn',
    zh_lz: 'cmn', zh_wh: 'cmn', zh_zz: 'cmn',
