for (const code of Object.keys(NEW_WORD_EVIDENCE)) {
    if (!LANG_DATA[code]) continue;
    if (!LANG_DATA[code].wordEvidence) LANG_DATA[code].wordEvidence = {};
    const wEv = LANG_DATA[code].wordEvidence;
    for (const w of Object.keys(NEW_WORD_EVIDENCE[code])) {
        if (!wEv[w]) wEv[w] = NEW_WORD_EVIDENCE[code][w];
    }
}
